package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;

public class B8cStructureManifestTest extends TestCase {
    private ObjectNode snapshot(){return (ObjectNode)parse("{\"id\":\"p\",\"sheetOrder\":[\"s\"],\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Sheet\",\"rowCount\":6,\"columnCount\":6,\"cellData\":{\"0\":{\"0\":{\"v\":\"a\",\"t\":1}},\"1\":{\"1\":{\"v\":\"b\",\"t\":1}},\"2\":{\"2\":{\"v\":\"c\",\"t\":1}},\"5\":{\"5\":{\"v\":\"z\",\"t\":1}}},\"rowData\":{\"2\":{\"h\":30}},\"columnData\":{\"2\":{\"w\":120}},\"mergeData\":[]}}}");}
    private ArrayNode scopes(){return (ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"A1:F6\"}]");}
    private ObjectNode action(String type,int index,int count,String position){ObjectNode a=obj().put("schemaVersion","2.0").put("type",type).put("count",count);a.set("target",obj().put("sheetId","s"));a.put(type.endsWith("Rows")?(type.startsWith("insert")?"rowIndex":"rowPosition"):(type.startsWith("insert")?"columnIndex":"columnPosition"),index);if(type.startsWith("insert"))a.put("position",position);else a.put("force",true);return a;}
    private void reject(Runnable r){try{r.run();fail("unsafe structure accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testFourTransitionsAndMetadata(){ObjectNode first=snapshot();for(String type:new String[]{"insertRows","deleteRows","insertColumns","deleteColumns"}){ObjectNode a=action(type,2,1,"at"),m=StructureManifest.preview(first,a,scopes()),saved=StructureManifest.apply(first,m);assertEquals(type.equals("insertRows")?7:type.equals("deleteRows")?5:6,saved.path("sheets").path("s").path("rowCount").asInt());assertEquals(type.startsWith("insert")&&type.endsWith("Columns")?7:type.equals("deleteColumns")?5:6,saved.path("sheets").path("s").path("columnCount").asInt());assertEquals("z",saved.path("sheets").path("s").path("cellData").path(type.equals("insertRows")?"6":type.equals("deleteRows")?"4":"5").path(type.equals("insertColumns")?"6":type.equals("deleteColumns")?"4":"5").path("v").asText());assertEquals("a",saved.path("sheets").path("s").path("cellData").path("0").path("0").path("v").asText());assertFalse(StableEffectLedger.identity(m).path("semanticKey").asText().isEmpty());}}
    public void testAfterPositionAndDeletionConfirmation(){ObjectNode m=StructureManifest.preview(snapshot(),action("insertRows",2,1,"after"),scopes());assertEquals(2,m.path("structurePatch").path("at").asInt());assertEquals("b",m.path("structurePatch").path("afterSheet").path("cellData").path("1").path("1").path("v").asText());ObjectNode noForce=action("deleteRows",2,1,"at");noForce.remove("force");reject(()->StructureManifest.preview(snapshot(),noForce,scopes()));ObjectNode bad=action("insertColumns",2,1,"before");reject(()->StructureManifest.preview(snapshot(),bad,scopes()));}
    public void testScopeAndDependenciesReject(){ObjectNode a=action("insertRows",2,1,"at");reject(()->StructureManifest.preview(snapshot(),a,(ArrayNode)parse("[{\"sheetId\":\"s\",\"range\":\"A1:E6\"}]")));ObjectNode formula=snapshot();((ObjectNode)formula.path("sheets").path("s").path("cellData").path("0").path("0")).put("f","=1+1");reject(()->StructureManifest.preview(formula,a,scopes()));ObjectNode merged=snapshot();((ArrayNode)merged.path("sheets").path("s").path("mergeData")).add(obj().put("startRow",0).put("startColumn",0).put("endRow",1).put("endColumn",1));reject(()->StructureManifest.preview(merged,a,scopes()));ObjectNode active=snapshot();active.set("resources",arr().add(obj().put("name","SHEET_FILTER_PLUGIN").put("data","{\"s\":{}}")));reject(()->StructureManifest.preview(active,a,scopes()));}
    public void testTamperReadbackAndSavedVerification(){ObjectNode initial=snapshot(),m=StructureManifest.preview(initial,action("deleteColumns",2,1,"at"),scopes()),saved=StructureManifest.apply(initial,m);StructureManifest.validateReceipt(m,m.path("structureReadback"));reject(()->StructureManifest.validateReceipt(m,obj().put("sheetId","s")));ObjectNode forged=m.deepCopy();((ObjectNode)forged.path("structurePatch")).put("count",2);reject(()->StructureManifest.apply(initial,forged));ObjectNode change=obj().put("kind","controlled-structure").put("operationId","call").put("afterHash",hash(saved));change.set("structurePatch",m.path("structurePatch"));ObjectNode write=obj().put("transportVersion",2).put("callId","call").put("persistenceStatus","SAVED").put("validation","PASSED").put("loadedRevision",hash(saved)).put("sourceRevision",hash(saved));write.set("executedChange",change);ObjectNode args=obj().put("kind","matches_structure").put("sheetId","s").put("range","A1:F6");args.set("write",write);assertTrue(AgentTools.verify(saved,args).path("passed").asBoolean());}
}

